<?php $root_id = $section_anchor ?: $section_instance; $title_id = platejka_section_dom_id( $section_instance, 'title' ); $list_id = platejka_section_dom_id( $section_instance, 'countries' ); $items = is_array( $section_data['items'] ?? null ) ? $section_data['items'] : array(); ?>
<section class="destinations" id="<?php echo esc_attr( $root_id ); ?>" data-destinations aria-labelledby="<?php echo esc_attr( $title_id ); ?>"><div class="container"><div class="destinations__panel" data-destinations-panel>
  <div class="destinations__content"><h2 id="<?php echo esc_attr( $title_id ); ?>"><?php echo esc_html( $section_data['title'] ?? '' ); ?></h2><div><?php echo wp_kses_post( $section_data['description'] ?? '' ); ?></div>
  <ul class="list-reset destinations__countries" id="<?php echo esc_attr( $list_id ); ?>" data-destinations-list><?php foreach ( $items as $index => $item ) : ?><li data-destinations-item<?php echo $index >= 10 ? ' data-destinations-extra hidden' : ''; ?>><?php echo platejka_section_image( $item['image'] ?? 0, 'thumbnail', array( 'loading' => 'lazy' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?><span><?php echo esc_html( $item['title'] ?? '' ); ?></span><div><?php echo wp_kses_post( $item['text'] ?? '' ); ?></div></li><?php endforeach; ?></ul>
  <button class="btn-reset destinations__more" type="button" data-destinations-toggle aria-expanded="false" aria-controls="<?php echo esc_attr( $list_id ); ?>"><span data-destinations-label><?php echo esc_html__( 'Показать ещё', 'platejka_rework' ); ?></span></button></div>
  <?php echo platejka_section_image( $section_data['image'] ?? 0, 'large', array( 'class' => 'destinations__globe', 'loading' => 'lazy' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
</div></div></section>
